/**
 * 渠道集成详情页模板（/integrations/<slug>/）
 *
 * 由 `gatsby-node.js` 的 `createPages` 从 `src/data/integrations.js` 生成 —— 一家一页。
 * 为什么走模板而不是在 `src/pages/` 下写十几个文件：内容全在数据里，加一家只改数据；
 * 手写多个文件必然漂移（一家改了字段另一家忘了）。
 *
 * 🔴 **本模板自 2026-10-14 起是通道无关的**：此前它把「SMS」写死在标题、眉标、
 *    范围框与「仍在客户名下」清单里 —— 数据源加入 EMAIL / WHATSAPP 条目后，
 *    那些字面量会让每一页都自称短信集成。现在通道相关的四处全部取自
 *    `channelMeta(integration.channel)`，**不得再在模板里出现 'SMS' 字面量**。
 *
 * 🔴 **`receipts` 字段决定范围框里那句回执说明** —— 它是本页唯一写回执的地方：
 *    `'delivery'` = 供应商已接线回执端点（短信全部 / Resend / Meta）；
 *    `'none'`     = 该供应商尚无回执端点，必须写明「只记受理结果」。
 *    这两句**不得合并**：把后者写成前者就是承诺一个做不到的动作（§6 同类问题）。
 *
 * 🔴 写作红线（真源 `sms-platform/docs/BSP角色与免责边界-对外文案稿.md` §6）：
 *    ① 不写「一个 API 对接三通道」；② 不做模板渲染/管理宣称；
 *    ③ **不把 SMS 专属能力（路由切换 / 分号码限速 / 分段计费 / STOP 关键词）写成三通道通用**。
 *    范围框（`.mk-scope`）就是把这条写在明面上的地方，**删它之前先回去读 §6**。
 *
 * 🔴 `softwareApp={false}`：本页不属于 Whaleal Cart 这个 Shopify 应用，
 *    不能让 SEO 组件输出 SoftwareApplication 结构化数据（那会向搜索引擎声明
 *    「本页讲的是一个 Shopify 应用」，是事实错误）。
 *
 * @author 恒哥
 * @since 2026-10-12
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { MESSAGING_PRODUCT_NAME, MESSAGING_CONNECTIONS_URL } from '../constants/brand';
import { channelMeta, INTEGRATION_STATS } from '../data/integrations';
import '../styles/marketing.css';

/** 回执说明 —— 两句话分别在 `receipts` 的两种取值下设为一处，避免各处重写后漂移 */
const RECEIPT_SENTENCE = {
  delivery:
    'Delivery events come back through the provider’s webhook and are normalized into the same three statuses as SMS, so a delivery reads the same way whichever channel carried it.',
  none:
    'This provider has no delivery webhook wired yet: a send is recorded with the acceptance outcome and any error code it returned, not with a later delivery status.',
};

export default function IntegrationTemplate({ pageContext }) {
  const { integration } = pageContext;
  const {
    name, tagline, summary, credentials, config, defaultRateLimit,
    requiresBaseUrl, requiresRegion, strengths, considerations, receipts,
  } = integration;

  const channel = channelMeta(integration.channel);
  const title = `${name} ${channel.noun} integration`;
  const description = `Connect your own ${name} account to ${MESSAGING_PRODUCT_NAME}: which credentials you need, what we configure, and the send pacing we apply.`;

  return (
    <Layout>
      <SEO
        title={title}
        description={description}
        pathname={`/integrations/${integration.slug}/`}
        softwareApp={false}
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: 'Integrations', path: '/integrations/' },
          { name, path: `/integrations/${integration.slug}/` },
        ]}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">{channel.label} · {tagline}</span>
          <h1>Connect your own {name} account</h1>
          <p className="mk-lead">{summary}</p>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={MESSAGING_CONNECTIONS_URL}>
              Add a {name} connection
            </a>
            <Link className="mk-btn mk-btn-secondary" to="/integrations/">
              All integrations
            </Link>
          </div>
        </header>

        <div className="mk-scope">
          <strong>Scope.</strong> This integration sends <strong>{channel.label}</strong>.{' '}
          {RECEIPT_SENTENCE[receipts]}{' '}
          {integration.channel === 'SMS' ? (
            <>
              Routing and automatic failover, per-number pacing and segment accounting are
              SMS-channel features.
            </>
          ) : (
            <>
              Routing and automatic failover, per-number pacing and segment accounting are
              SMS-channel features rather than {channel.label} ones: a {channel.label} send goes out
              on the single connection you configure.
            </>
          )}{' '}
          Opt-out suppression is applied to marketing sends on every channel.{' '}
          {MESSAGING_PRODUCT_NAME} is a message <em>orchestration</em> layer: it calls {name}&rsquo;s
          public API using <strong>your</strong> account. We do not resell message volume, do not
          mark up your {name} bill, and do not own your account.
        </div>

        <section className="mk-section">
          <h2>What you need from {name}</h2>
          <p className="mk-section-lead">
            Gather these in the {name} portal first. The connection form asks for exactly these
            fields and nothing more.
          </p>
          <table className="mk-table">
            <thead>
              <tr>
                <th>Field</th>
                <th>What it is</th>
              </tr>
            </thead>
            <tbody>
              {credentials.map((c) => (
                <tr key={c.key}>
                  <td className="mk-field-list">
                    {c.key}
                    {c.optional && <span className="mk-field-optional">optional</span>}
                  </td>
                  <td>
                    <strong>{c.label}.</strong> {c.note}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="mk-section-lead">
            Credentials are sealed with AES-256-GCM and the console only ever shows a masked value
            afterwards. Plaintext is never written to logs and never sent back to the browser.
          </p>
        </section>

        <section className="mk-section">
          <h2>What we configure on the connection</h2>
          <ul className="mk-list">
            {config.map((c) => (
              <li key={c.key}>
                <strong>{c.label}.</strong> {c.note}
              </li>
            ))}
            <li>
              <strong>Default send pacing: {defaultRateLimit === 0 ? 'unlimited' : `${defaultRateLimit} message${defaultRateLimit === 1 ? '' : 's'} per second`}.
              </strong>{' '}
              This is a conservative starting point, applied per connection, and you can change it at
              any time. Your real ceiling is set by {name} — check your account quota and raise the
              value to match.
            </li>
            {requiresBaseUrl && (
              <li>
                <strong>Base URL is required.</strong> {name} issues a per-account API host; the
                connection will not work with a guessed regional hostname.
              </li>
            )}
            {requiresRegion && (
              <li>
                <strong>Region is required.</strong> Sending quotas and available sender identities
                differ per region.
              </li>
            )}
          </ul>
        </section>

        <section className="mk-section">
          <h2>Why teams pick {name}</h2>
          <ul className="mk-list">
            {strengths.map((s) => (
              <li key={s}>{s}</li>
            ))}
          </ul>
        </section>

        {considerations.length > 0 && (
          <section className="mk-section">
            <h2>Worth knowing</h2>
            <ul className="mk-list">
              {considerations.map((s) => (
                <li key={s}>{s}</li>
              ))}
            </ul>
          </section>
        )}

        <section className="mk-section">
          <h2>What stays on your side</h2>
          <p className="mk-section-lead">
            These are yours to hold — and that is the point of bringing your own account: the
            relationship, the rates and the compliance stay in your name, not ours.
          </p>
          <ul className="mk-list mk-list-plain">
            {channel.holds.map((h) => (
              <li key={h}>{h.replace('{name}', name)}</li>
            ))}
          </ul>
        </section>

        <section className="mk-section">
          <h2>Next</h2>
          <p className="mk-section-lead">
            {MESSAGING_PRODUCT_NAME} currently offers self-service connections to{' '}
            {INTEGRATION_STATS.byChannel.SMS} SMS providers,{' '}
            {INTEGRATION_STATS.byChannel.EMAIL} email providers and{' '}
            {INTEGRATION_STATS.byChannel.WHATSAPP} WhatsApp providers. Underlying the SMS channel is
            an SMS adapter library of {INTEGRATION_STATS.sdkAdapters} adapters; the ones outside
            this list are unlocked on request rather than self-service.
          </p>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={MESSAGING_CONNECTIONS_URL}>
              Add the connection
            </a>
            <Link className="mk-btn mk-btn-secondary" to="/messaging/">
              How {MESSAGING_PRODUCT_NAME} works
            </Link>
          </div>
        </section>
      </div>
    </Layout>
  );
}
